create table if not exists public.hms_guest_documents(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null,guest_id uuid not null,document_type text not null,document_number text,document_url text,verified boolean not null default false,verified_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.hms_guest_deposits(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null,reservation_id uuid,stay_id uuid,amount numeric not null check(amount>=0),method text not null,reference text,status text not null default 'held',created_at timestamptz not null default now(),released_at timestamptz);
create table if not exists public.hms_folio_payments(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null,folio_id uuid not null,amount numeric not null check(amount>0),method text not null,provider text,reference text,status text not null default 'settled',created_at timestamptz not null default now());
create table if not exists public.hms_maintenance_tasks(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null,room_id uuid,task_type text not null,priority text not null default 'normal',status text not null default 'open',assigned_to uuid,notes text,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.hms_night_audits(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null,business_date date not null,status text not null default 'started',occupancy numeric,room_revenue numeric,restaurant_revenue numeric,total_revenue numeric,evidence jsonb not null default '{}'::jsonb,started_at timestamptz not null default now(),completed_at timestamptz,unique(restaurant_id,business_date));
create table if not exists public.crm_workflow_queue(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,workflow_id uuid not null,run_id uuid,action_index int not null default 0,action jsonb not null default '{}'::jsonb,status text not null default 'queued',attempts int not null default 0,last_error text,available_at timestamptz not null default now(),claimed_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.crm_forecast_points(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,run_id uuid not null,metric_date date not null,metric text not null,value numeric,lower_bound numeric,upper_bound numeric,created_at timestamptz not null default now());
